/// <summary>
/// Transport class for importing messages from an Azure container including its sub-directories
/// </summary>
class OMGInboundTransport_AzureContainerSubDir extends OMGInboundTransport_AzureContainer
{        
}

Method.Source:
/// <summary>
/// Description of class
/// </summary>
/// <returns>The description</returns>
public static Description description()
{
    return "@OMG:ImportFromAzureContainerSubDir";
}

public void doTransport(OMGInboundTransportContract _transportContract)
{        
    OMGMessageTypeTable                     messageTypeTable = OMGMessageTypeTable::find(_transportContract.parmMessageTypeId());        
    str                                     archiveContainer;                
    Map                                     fileMap;       
    ;

    dataContract = FormJsonSerializer::deserializeObject(this.dataContractClass(), messageTypeTable.InboundSerializedParameterContract) as OMGInboundDataContract_AzureContainerSubDir;

    if (dataContract.parmArchiveUnderSubDir() == NoYes::Yes)
    {
        archiveContainer = dataContract.parmArchiveContainerName();
    }
    else
    {
        archiveContainer = dataContract.parmArchiveContainer();
    }

    azureContainerReader = OMGAzureContainerReader::newParameters(dataContract.parmKeyVaultCertificateRef(),
                                                                  dataContract.parmSourceContainer(),
                                                                  archiveContainer,
                                                                  dataContract.parmFileTypeFilter(),
                                                                  dataContract.parmPostImportAction(),
                                                                  NoYes::Yes,
                                                                  dataContract.parmArchiveUnderSubDir());                                                                      

    fileMap = azureContainerReader.buildFileHandleMap();

    this.processFileMap(fileMap, dataContract.parmCodePage(), messageTypeTable.MessageTypeId);

    info(strFmt("@OMG:MessagesFetched", messageTypeTable.MessageTypeId, messageCounter));
}
